import {RenderTarget,FloatType,RGFormat,NearestFilter,NodeMaterial,QuadMesh,Vector2} from 'three/webgpu';
import * as T from 'three/tsl';
import {depthHierarchyLayout} from './hierarchical-depth.js';
export class GPUHierarchicalDepthPass{
 constructor(){this.levels=[];this.layout=null;this.atlas=null;this.source=T.texture();this.depth=T.texture();this.size=T.uniform(new Vector2());this.materials=[true,false].map(first=>{const material=new NodeMaterial();material.depthTest=material.depthWrite=false;material.fragmentNode=T.Fn(()=>{const at=T.ivec2(T.screenCoordinate.xy).mul(2),range=T.vec2(1,0).toVar();for(let y=0;y<2;y++)for(let x=0;x<2;x++){const sample=T.textureLoad(first?this.depth:this.source,T.min(at.add(T.ivec2(x,y)),T.ivec2(this.size).sub(1))),value=first?T.vec2(sample):sample.rg;range.assign(T.vec2(T.min(range.x,value.x),T.max(range.y,value.y)));}return T.vec4(range,0,1);})();return material;});this.quad=new QuadMesh(this.materials[0]);}
 setSize(w,h){if(this.layout?.sourceWidth===w&&this.layout?.sourceHeight===h)return;this.release();this.layout={...depthHierarchyLayout(w,h),sourceWidth:w,sourceHeight:h};const options={type:FloatType,format:RGFormat,minFilter:NearestFilter,magFilter:NearestFilter,depthBuffer:false};this.atlas=new RenderTarget(this.layout.width,this.layout.height,options);this.levels=this.layout.levels.map(l=>new RenderTarget(l.width,l.height,options));}
 render(renderer,depth,w,h){this.setSize(w,h);const target=renderer.getRenderTarget(),mrt=renderer.getMRT();try{renderer.setMRT(null);renderer.setRenderTarget(this.atlas);renderer.clear();this.depth.value=depth;this.size.value.set(w,h);for(let i=0;i<this.levels.length;i++){const l=this.levels[i];this.quad.material=this.materials[i===0?0:1];renderer.setRenderTarget(l);this.quad.render(renderer);renderer.copyTextureToTexture(l.texture,this.atlas.texture,null,new Vector2(0,this.layout.levels[i].y));this.source.value=l.texture;this.size.value.set(l.width,l.height);}}finally{renderer.setRenderTarget(target);renderer.setMRT(mrt);}return this.atlas.texture;}
 release(){this.atlas?.dispose();for(const l of this.levels)l.dispose();this.atlas=null;this.levels=[];this.layout=null;}
 dispose(){this.release();for(const material of this.materials)material.dispose();}
}
